// Demo caseload for the PT dashboard when no server is connected. Each patient is
// generated by replaying real sessions through the progression engine, so the coach
// changes, alerts and RTM counts are what the engine would actually produce.
import * as E from './engine.js';

const DAY = 86400000;
const ago = (d, hour = 18) => { const t = new Date(Date.now() - d * DAY); t.setHours(hour, 0, 0, 0); return t.toISOString(); };
const dateAgo = d => ago(d).slice(0, 10);
const parts = (m, s, c, y) => ({ mobility: m, stability: s, control: c, symmetry: y });

function build(p) {
  const sp = E.startSprint(p.sprintId);
  sp.startedAt = ago(p.start, 9);
  for (const [d, pain, effort = 'right', note = ''] of p.sessions) {
    const log = { at: ago(d), idx: sp.sessions.length, pain, effort, note, done: [] };
    sp.sessions.push(log);
    const before = sp.changes.length;
    E.progress(sp, log, p.painBaseline);
    sp.changes.slice(before).forEach(ch => { ch.at = log.at; });
  }
  return {
    id: p.id, demo: true, created: ago(p.start, 8), plan: p.plan || 'member', ref: p.ref || null, quiet: !!p.quiet,
    profile: { name: p.name, age: p.age, state: p.state, door: p.door, sprintId: p.sprintId, painBaseline: p.painBaseline, goal: p.goal,
      flags: p.flags || [], outOfState: !['VA', 'NC', 'MD', 'DC', 'TX'].includes(p.state), joined: ago(p.start, 8), urgentFlag: p.urgent ? ago(1, 20) : null },
    sprint: sp,
    scores: (p.scores || []).map(([d, total, pt, method = 'camera']) => ({ at: ago(d, 10), total, parts: pt, method, tests: {} })),
    checkins: (p.checkins || []).map(([d, pain]) => ({ at: ago(d, 7), pain })),
    pads: (p.pads || []).map(([d, count]) => ({ date: dateAgo(d), count })),
    coach: (p.coach || []).map(([role, text, d]) => ({ role, text, at: ago(d, 19), source: role === 'coach' ? 'ai' : undefined })),
    visits: (p.visits || []).map(([d], i) => ({ id: 'dv' + p.id + i, requested: ago(d, 12), status: 'requested' })),
    formChecks: p.formChecks || [],
  };
}

